  Ciphertext q3 = v - one;             // 2u - 1
  Ciphertext r = v * c5 + c3;          // c3 + 2 c5 u, level 3
  Ciphertext inner = q3 * r + c1 - c5; // level 4
  Ciphertext result = z * inner + c0;  // level 5
